BEGIN
  PERFORM public.validate_ticket_layout(layout);
  FOREACH bad IN ARRAY ARRAY[
    jsonb_set(layout, '{templates,wide,elements,6,text}', '42'),
    jsonb_set(layout, '{templates,wide,elements,6,text}', to_jsonb(repeat('x',2001))),
